                </div>
                <p className="mb-4 mt-6 text-lg text-bold">{warningTitle}</p>
                <StripedList alternate="odd" className="mt-0">
                    {warningPoints.map((text) => (
                        <StripedItem key={text} left={<Icon name="cross-big" className="color-danger" />}>
