            expirationDate: subscriptionMock.PeriodEnd,
        });
    });

    it('uses the active term when the upcoming subscription has renewal disabled', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                UpcomingSubscription: {
                    ...upcomingSubscriptionMock,
                    Renew: Renew.Disabled,
                    Plans: [{ ...upcomingSubscriptionMock.Plans[0], Title: 'Future plan' }],
                },
            })
        ).toEqual({
            subscriptionExpiresSoon: true,
            planName: 'Proton Unlimited',
            renewDisabled: true,
            renewEnabled: false,
            expirationDate: subscriptionMock.PeriodEnd,
        });
    });

    it('should handle the case when the upcoming subscription does not expire', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                UpcomingSubscription: {
                    ...upcomingSubscriptionMock,
                    Renew: Renew.Enabled,
                    Plans: [{ ...upcomingSubscriptionMock.Plans[0], Title: 'Future plan' }],
                },
            })
        ).toEqual({
            subscriptionExpiresSoon: false,
            planName: 'Future plan',
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });

    it('uses the active term when cancellation is in progress, even if the upcoming term does not expire', () => {
        expect(
            subscriptionExpires(
                {
                    ...subscriptionMock,
                    UpcomingSubscription: {
                        ...upcomingSubscriptionMock,
                        Plans: [{ ...upcomingSubscriptionMock.Plans[0], Title: 'Future plan' }],
                    },
                },
                true
            )
        ).toEqual({
            subscriptionExpiresSoon: true,
            planName: 'Proton Unlimited',
            renewDisabled: true,
            renewEnabled: false,
            expirationDate: subscriptionMock.PeriodEnd,
        });
    });

    it('uses the active term when its auto-renew is disabled, even if the upcoming term would renew', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                Renew: Renew.Disabled,
                UpcomingSubscription: upcomingSubscriptionMock,
            })
        ).toEqual({
            subscriptionExpiresSoon: true,
            planName: 'Proton Unlimited',
            renewDisabled: true,
            renewEnabled: false,
            expirationDate: subscriptionMock.PeriodEnd,
        });
    });
});

