export function subscriptionExpires(): FreeSubscriptionResult;
export function subscriptionExpires(subscription: undefined | null, cancellationContext?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(subscription: FreeSubscription, cancellationContext?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel | undefined, cancellationContext?: boolean): SubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel, cancellationContext?: boolean): SubscriptionResult;
export function subscriptionExpires(
    subscription?: SubscriptionModel | FreeSubscription | null,
    cancellationContext = false
): FreeSubscriptionResult | SubscriptionResult {
    if (!subscription || isFreeSubscription(subscription)) {
        return {
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        };
    }

    const latestSubscription = subscription.UpcomingSubscription ?? subscription;
    if (cancellationContext || subscription.Renew === Renew.Disabled || latestSubscription.Renew === Renew.Disabled) {
        return {
            subscriptionExpiresSoon: true,
            renewDisabled: true,
            renewEnabled: false,
            planName: subscription.Plans?.[0]?.Title,
            expirationDate: subscription.PeriodEnd,
        };
    }

    const renewEnabled = latestSubscription.Renew === Renew.Enabled;
    const planName = latestSubscription.Plans?.[0]?.Title;

    return {
        subscriptionExpiresSoon: false,
        renewDisabled: false,
        renewEnabled,
        planName,
        expirationDate: null,
    };
}

